/**
 *
 * RatingOn is the filled/active icon layer of a Rating star. It is absolutely
 * positioned and clipped to show full, half, or no fill based on the active value.
 *
 * [Live Demo](https://www.primereact.org/rating/)
 *
 * @module RatingOn
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { RatingRootInstance } from './RatingRoot.types';
/**
 * Defines passthrough(pt) options type in RatingOn component.
 */
export type RatingOnPassThroughType<E> = PassThroughType<RatingOnInstance, E>;
/**
 * Defines passthrough(pt) options of RatingOn component.
 */
export interface RatingOnPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: RatingOnPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in RatingOn component.
 */
export interface RatingOnProps extends BaseComponentProps<RatingOnInstance, unknown, RatingOnPassThrough> {
}
/**
 * Defines valid state in RatingOn component.
 */
export interface RatingOnState {
}
/**
 * Defines the methods and properties exposed by RatingOn component.
 */
export interface RatingOnExposes {
    /**
     * The parent Rating component instance.
     */
    rating: RatingRootInstance | undefined | null;
    /**
     * The parent RatingOption component instance.
     */
    ratingOption: import('./RatingOption.types').RatingOptionInstance | undefined | null;
}
/**
 * Instance of RatingOn component.
 */
export type RatingOnInstance = ComponentInstance<RatingOnProps, RatingOnState, RatingOnExposes>;
